<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Bus; use App\Models\Route; use App\Models\Stop; use Illuminate\Http\Request;
class RouteController extends Controller { public function index(){return view('admin.routes.index',['routes'=>Route::with('bus')->latest()->paginate(10)]);} public function create(){return view('admin.routes.form',['route'=>new Route,'buses'=>Bus::orderBy('name')->get(),'stops'=>Stop::orderBy('name')->get()]);} public function store(Request $r){$route=Route::create($this->data($r));$this->sync($r,$route);return redirect()->route('admin.routes.index')->with('success','Rute berhasil ditambahkan.');} public function edit(Route $route){$route->load('stops');return view('admin.routes.form',['route'=>$route,'buses'=>Bus::orderBy('name')->get(),'stops'=>Stop::orderBy('name')->get()]);} public function update(Request $r,Route $route){$route->update($this->data($r));$this->sync($r,$route);return redirect()->route('admin.routes.index')->with('success','Rute diperbarui.');} public function destroy(Route $route){$route->delete();return back()->with('success','Rute dihapus.');} private function data(Request $r){return $r->validate(['bus_id'=>'required|exists:buses,id','name'=>'required|max:100','direction'=>'required|max:40','description'=>'nullable','path_coordinates'=>'nullable']);} private function sync(Request $r,Route $route){$ids=$r->input('stops',[]);$route->stops()->sync(collect($ids)->values()->mapWithKeys(fn($id,$i)=>[$id=>['sequence'=>$i+1]]));} }
